31	const ROOT = path.join(__dirname, '..', '..');
32	const PREDICTIONS_FILE = path.join(ROOT, 'data', 'assets', 'calibration', 'predictions.json');
33	const PERSONAS_DIR = path.join(__dirname, '..', 'skills', 'business', 'personas');
34	const REVIEW_STATE_FILE = path.join(ROOT, 'data', 'assets', 'calibration', 'last-weekly-review.json');
35	const BRIER_FILE = path.join(ROOT, 'data', 'calibration', 'brier-scores.jsonl');
36	const SKIP_DIRS = new Set(['shared', 'young-masters', '_template']);
37	const WEEKLY_INTERVAL_MS = 7 * 24 * 60 * 60 * 1000;
38	const EVOLUTION_CONFIG_PATH = path.join(__dirname, '..', 'data', 'evolution-config.json');
