52	function isEvolutionDue() {
53	  const config = loadJson(EVOLUTION_CONFIG_PATH);
54	  if (!config) return true;
55	  const lastRun = config.last_evolution_run;
56	  if (!lastRun) return true;
57	  try {
58	    const age = Date.now() - new Date(lastRun).getTime();
59	    return age > WEEKLY_INTERVAL_MS;
60	  } catch {
61	    return true;
62	  }
63	}
