65	/**
66	 * Parse YYMMDD date string used in pulse_due_date field.
67	 * Returns a Date or null on error.
68	 */
69	function parsePulseDueDate(str) {
70	  if (!str || str.length !== 6) return null;
71	  try {
72	    const yy = parseInt(str.slice(0, 2), 10);
73	    const mm = parseInt(str.slice(2, 4), 10) - 1; // 0-indexed
74	    const dd = parseInt(str.slice(4, 6), 10);
75	    const year = 2000 + yy;
76	    return new Date(year, mm, dd);
77	  } catch {
78	    return null;
79	  }
80	}
81	
82	/**
83	 * Returns pending brier-score entries where observed == null AND pulse_due_date <= today.
84	 * Returns up to 5 most recent, sorted by ts_created desc.
85	 */
86	function getPendingBrierOutcomes() {
87	  if (!fs.existsSync(BRIER_FILE)) return [];
88	  const today = new Date();
89	  today.setHours(0, 0, 0, 0);
90	
91	  const pending = [];
92	  let raw;
93	  try {
94	    raw = fs.readFileSync(BRIER_FILE, 'utf8');
95	  } catch {
96	    return [];
97	  }
98	
99	  for (const line of raw.split('\n')) {
100	    const trimmed = line.trim();
101	    if (!trimmed) continue;
102	    let entry;
103	    try {
104	      entry = JSON.parse(trimmed);
105	    } catch {
106	      continue;
107	    }
108	    if (entry.observed !== null && entry.observed !== undefined) continue;
109	
110	    const due = parsePulseDueDate(entry.pulse_due_date);
111	    if (!due) continue;
112	    if (due > today) continue;  // not yet due
113	
114	    pending.push(entry);
115	  }
116	
117	  // Sort by ts_created descending, take 5 most recent
118	  pending.sort((a, b) => {
119	    const ta = a.ts_created || '';
120	    const tb = b.ts_created || '';
121	    return tb.localeCompare(ta);
122	  });
123	  return pending.slice(0, 5);
124	}
