126	function getExpiredLegacyPredictions() {
127	  const raw = loadJson(PREDICTIONS_FILE);
128	  if (!raw || !Array.isArray(raw.predictions)) return [];
129	
130	  const now = new Date();
131	  return raw.predictions.filter(p => {
132	    if (p.outcome != null) return false;
133	    const deadline = p.verification_date || p.outcome_date;
134	    if (!deadline) {
135	      // No explicit deadline — check if prediction is >30 days old
136	      try {
137	        const created = new Date(p.timestamp);
138	        return (now - created) > 30 * 24 * 60 * 60 * 1000;
139	      } catch { return false; }
140	    }
141	    try {
142	      return new Date(deadline) < now;
143	    } catch { return false; }
144	  });
145	}
146	
147	function getExpiredCalibrationPredictions() {
148	  const expired = [];
149	  if (!fs.existsSync(PERSONAS_DIR)) return expired;
150	
151	  const now = new Date();
152	  const entries = fs.readdirSync(PERSONAS_DIR, { withFileTypes: true });
153	
154	  for (const entry of entries) {
155	    if (!entry.isDirectory() || SKIP_DIRS.has(entry.name)) continue;
156	    const calPath = path.join(PERSONAS_DIR, entry.name, 'knowledge', 'calibration-log.json');
157	    const log = loadJson(calPath);
158	    if (!Array.isArray(log)) continue;
159	
160	    for (const pred of log) {
161	      if (pred.outcome != null) continue;
162	      if (pred.type === 'recommendation') continue;
163	
164	      const deadline = pred.verification_date;
165	      if (deadline) {
166	        try {
167	          if (new Date(deadline) < now) {
168	            expired.push({ ...pred, _persona: entry.name, _store: 'calibration' });
169	          }
170	        } catch { /* skip */ }
171	      } else {
172	        // No deadline — check if >30 days old
173	        try {
174	          const created = new Date(pred.timestamp);
175	          if ((now - created) > 30 * 24 * 60 * 60 * 1000) {
176	            expired.push({ ...pred, _persona: entry.name, _store: 'calibration' });
177	          }
178	        } catch { /* skip */ }
179	      }
180	    }
181	  }
182	  return expired;
183	}
