1	#!/usr/bin/env node
2	/**
3	 * Stop Hook - Full Learning Loop Wire
4	 *
5	 * Fires: After /stage0, /startup, /brainstorm completes (Stop event)
6	 * Purpose: Wire 3 disconnected learning systems:
7	 *   1. usage-count-tracker.py — Track SCH/MM/ARCH pattern citations
8	 *   2. experience-outcome-resolver.py — Resolve null outcomes in experience-bank
9	 *   3. stage0-outcomes-db-writer.py — Write verdicts to outcomes.db
10	 *
11	 * Exit: 0 always (non-blocking, fail-open)
12	 */
13	'use strict';
14	
15	const fs = require('fs');
16	const path = require('path');
17	const { spawnSync } = require('child_process');
18	
19	let isHookEnabled;
20	try {
21	  ({ isHookEnabled } = require('./lib/ck-config-utils.cjs'));
22	} catch {
23	  isHookEnabled = () => true;
24	}
25	
26	if (!isHookEnabled('learning-loop-full-wire')) {
27	  process.exit(0);
28	}
29	
30	const ROOT = path.resolve(__dirname, '..', '..');
31	const PYTHON_SUBPATH = process.platform === 'win32' ? 'Scripts/python.exe' : 'bin/python3';
32	const PYTHON = path.join(ROOT, '.claude', 'skills', '.venv', PYTHON_SUBPATH);
33	const FEEDBACK_DIR = path.join(ROOT, '.claude', 'skills', 'business', 'feedback_loop');
34	const LOG_DIR = path.join(__dirname, '.logs');
35	
36	const SCRIPTS = {
37	  usageTracker: path.join(FEEDBACK_DIR, 'usage-count-tracker.py'),
38	  experienceResolver: path.join(FEEDBACK_DIR, 'experience-outcome-resolver.py'),
39	  outcomesWriter: path.join(FEEDBACK_DIR, 'stage0-outcomes-db-writer.py'),
40	  brainFeeder: path.join(FEEDBACK_DIR, 'experience-brain-feeder.py'),
41	};
42	
43	function log(msg) {
44	  try {
45	    fs.mkdirSync(LOG_DIR, { recursive: true });
46	    fs.appendFileSync(
47	      path.join(LOG_DIR, 'hook-log.jsonl'),
48	      JSON.stringify({ ts: new Date().toISOString(), hook: 'learning-loop-full-wire', msg }) + '\n'
49	    );
50	  } catch {}
51	}
52	
53	function runPython(script, inputData) {
54	  if (!fs.existsSync(PYTHON) || !fs.existsSync(script)) {
55	    return null;
56	  }
57	  try {
58	    const result = spawnSync(PYTHON, [script], {
59	      encoding: 'utf-8',
60	      input: inputData || '',
61	      timeout: 15000,
62	      cwd: ROOT,
63	    });
64	    if (result.stdout) {
65	      try { return JSON.parse(result.stdout); } catch { return null; }
66	    }
67	    return null;
68	  } catch {
69	    return null;
70	  }
71	}
72	
73	function main() {
74	  // Read Stop hook payload
75	  let payload = {};
76	  try {
77	    const raw = fs.readFileSync(0, 'utf-8');
78	    if (raw) payload = JSON.parse(raw);
79	  } catch {
80	    process.exit(0);
81	  }
82	
83	  const userPrompt = payload.user_prompt || payload.last_user_message || '';
84	  const assistantMessage = payload.assistant_message || payload.last_message || payload.content || '';
85	
86	  // Only fire on pipeline commands
87	  const COMMAND_RE = /\/(stage0|startup|brainstorm|invest|venture|launch)\b/i;
88	  if (!COMMAND_RE.test(userPrompt) && !COMMAND_RE.test(assistantMessage)) {
89	    process.exit(0);
90	  }
91	
92	  if (!assistantMessage || assistantMessage.length < 100) {
93	    process.exit(0);
94	  }
95	
96	  const inputJson = JSON.stringify({
97	    user_prompt: userPrompt,
98	    assistant_message: assistantMessage,
99	  });
100	
101	  const messages = [];
102	
103	  // 1. Track pattern usage (SCH/MM/ARCH citations)
104	  const usageResult = runPython(SCRIPTS.usageTracker, inputJson);
105	  if (usageResult && usageResult.found > 0) {
106	    messages.push(`Pattern tracking: ${usageResult.found} patterns cited (${usageResult.pattern_ids.join(', ')})`);
107	    log({ script: 'usage-tracker', result: usageResult });
108	  }
109	
110	  // 2. Write to outcomes.db
111	  const dbResult = runPython(SCRIPTS.outcomesWriter, inputJson);
112	  if (dbResult && dbResult.ingested) {
113	    messages.push(`Outcomes DB: ${dbResult.verdict} → ${dbResult.decision_type} (signal #${dbResult.signal_id})`);
114	    log({ script: 'outcomes-writer', result: dbResult });
115	  }
116	
117	  // 3. Resolve experience-bank outcomes (runs --resolve, no stdin needed)
118	  const resolveResult = runPython(SCRIPTS.experienceResolver, '--resolve');
119	  // experienceResolver expects args not stdin for --resolve, use spawnSync directly
120	  if (!resolveResult) {
121	    try {
122	      const r = spawnSync(PYTHON, [SCRIPTS.experienceResolver, '--resolve'], {
123	        encoding: 'utf-8',
124	        timeout: 10000,
125	        cwd: ROOT,
126	      });
127	      if (r.stdout) {
128	        const parsed = JSON.parse(r.stdout);
129	        if (parsed.resolved > 0) {
130	          messages.push(`Experience bank: ${parsed.resolved} outcomes resolved`);
131	          log({ script: 'experience-resolver', result: parsed });
132	        }
133	      }
134	    } catch {}
135	  }
136	
137	  // 4. Feed ExperienceBrain with new experience-bank rows
138	  try {
139	    const brainResult = spawnSync(PYTHON, [SCRIPTS.brainFeeder], {
