13	'use strict';
14	
15	const fs = require('fs');
16	const path = require('path');
17	const { spawnSync, spawn } = require('child_process');
18	
19	let isHookEnabled;
20	try {
21	  ({ isHookEnabled } = require('./lib/ck-config-utils.cjs'));
22	} catch {
23	  isHookEnabled = () => true;
