30	const DEBUG = !!process.env.CK_DEBUG;
31	
32	function log(tag, msg) {
33	  if (DEBUG) console.error(`[${tag}] ${msg}`);
34	}
35	
36	// ---------------------------------------------------------------------------
37	// Shared helpers
38	// ---------------------------------------------------------------------------
39	
40	function isoWeekId(date) {
41	  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
42	  const day = d.getUTCDay() || 7;
43	  d.setUTCDate(d.getUTCDate() + 4 - day);
44	  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
45	  const week = Math.ceil(((d - yearStart) / 86400000 + 1) / 7);
46	  return `${d.getUTCFullYear()}-W${String(week).padStart(2, '0')}`;
47	}
48	
49	// ---------------------------------------------------------------------------
50	// Task 1: Meta-learner weekly digest + Hebbian edge decay
51	// ---------------------------------------------------------------------------
52	
53	function metaLearnerWeekly(repoRoot) {
54	  const tag = 'meta-learner';
55	  try {
56	    const weekId = isoWeekId(new Date());
57	    const digestPath = path.join(repoRoot, 'data', 'meta-learning', `${weekId}-digest.md`);
58	
59	    if (fs.existsSync(digestPath)) return; // already written this week
60	
61	    const pythonExe = path.join(repoRoot, '.claude', 'skills', '.venv', 'Scripts', 'python.exe');
62	    const script = path.join(repoRoot, '.claude', 'skills', 'business', 'compound', 'meta-learning-weekly-digest.py');
63	
64	    if (!fs.existsSync(pythonExe) || !fs.existsSync(script)) return;
65	
66	    const result = spawnSync(pythonExe, [script], { encoding: 'utf-8', timeout: 30000 });
67	    if (DEBUG && result.stderr) log(tag, result.stderr.trim());
68	    if (DEBUG && result.error) log(tag, result.error.message);
69	
70	    // Hebbian edge decay (skipped internally if already ran this week)
71	    const decayScript = path.join(repoRoot, '.claude', 'skills', 'business', 'feedback_loop', 'hebbian-edge-decay.py');
72	    if (fs.existsSync(decayScript)) {
73	      const dr = spawnSync(pythonExe, [decayScript], { encoding: 'utf-8', timeout: 15000 });
74	      if (DEBUG && dr.stderr) log(tag, `decay: ${dr.stderr.trim()}`);
75	    }
76	
77	    if (fs.existsSync(digestPath)) {
78	      const output = {
79	        hookSpecificOutput: {
80	          hookEventName: 'SessionStart',
81	          additionalContext: `Weekly meta-learner digest written: data/meta-learning/${weekId}-digest.md`,
82	        },
83	      };
84	      console.log(JSON.stringify(output));
85	    }
86	  } catch (e) {
87	    log(tag, e.message);
88	  }
89	}
90	
91	// ---------------------------------------------------------------------------
92	// Task 2: Cognitive consolidation (detached, >=12h or >50 new items)
93	// ---------------------------------------------------------------------------
94	
95	function cognitiveConsolidation(repoRoot) {
96	  const tag = 'cognitive-cron';
97	  try {
98	    const cogRoot = path.join(repoRoot, 'data', 'cognitive');
99	    const customDir = path.join(cogRoot, 'custom');
100	    const logPath = path.join(customDir, 'consolidation-log.jsonl');
101	    const cronLog = path.join(customDir, 'consolidation-cron.log');
102	    const pendingDb = path.join(customDir, 'pending-inferences.db');
103	    const bayesianDb = path.join(customDir, 'bayesian.db');
104	
105	    const pythonExe = path.join(cogRoot, '.venv', 'Scripts', 'python.exe');
106	    const script = path.join(cogRoot, 'scripts', 'consolidate', 'cognitive-consolidate.py');
107	
108	    if (!fs.existsSync(pythonExe) || !fs.existsSync(script)) return;
109	
110	    function lastRunEntry() {
111	      if (!fs.existsSync(logPath)) return null;
112	      try {
113	        const lines = fs.readFileSync(logPath, 'utf8').trim().split('\n').filter(Boolean);
114	        for (let i = lines.length - 1; i >= 0; i--) {
115	          try {
116	            const e = JSON.parse(lines[i]);
117	            if (e.action === 'consolidate_run' && e.finished_at) return e.finished_at;
118	          } catch (_) {}
119	        }
120	      } catch (_) {}
121	      return null;
122	    }
123	
124	    const lastIso = lastRunEntry();
125	    const hoursAgo = lastIso ? (Date.now() - new Date(lastIso).getTime()) / 3600000 : Infinity;
126	
127	    let newItems = 0;
128	    const since = lastIso ? new Date(lastIso).getTime() : 0;
129	    for (const db of [pendingDb, bayesianDb]) {
130	      if (!fs.existsSync(db)) continue;
131	      try {
132	        const stat = fs.statSync(db);
133	        if (stat.mtimeMs > since) newItems += Math.max(1, Math.floor(stat.size / 200));
134	      } catch (_) {}
135	    }
136	
137	    const shouldRun = process.env.COGNITIVE_CRON_FORCE === '1' || hoursAgo >= 12 || newItems > 50;
138	    if (!shouldRun) {
139	      log(tag, `skipped (hours=${hoursAgo.toFixed(1)}, new=${newItems})`);
140	      return;
141	    }
142	
143	    fs.mkdirSync(customDir, { recursive: true });
144	    const out = fs.openSync(cronLog, 'a');
145	    const err = fs.openSync(cronLog, 'a');
146	    const child = spawn(pythonExe, [script], {
147	      cwd: cogRoot, detached: true, stdio: ['ignore', out, err], windowsHide: true,
148	    });
149	    child.unref();
150	    log(tag, `launched pid=${child.pid} (hours=${hoursAgo.toFixed(1)}, new=${newItems})`);
151	  } catch (e) {
152	    log(tag, e.message);
153	  }
154	}
155	
156	// ---------------------------------------------------------------------------
157	// Task 3: Brain refresh weekly (detached, >7 days since last run)
158	// ---------------------------------------------------------------------------
159	
160	function brainRefreshWeekly(repoRoot) {
161	  const tag = 'brain-refresh';
162	  try {
163	    let enabled = true;
164	    let minDays = 7;
165	    try {
166	      const cfg = JSON.parse(fs.readFileSync(path.join(repoRoot, '.claude', '.ck.json'), 'utf-8'));
167	      enabled = cfg?.stage0?.brainRefresh?.enabled ?? true;
168	      minDays = cfg?.stage0?.brainRefresh?.minIntervalDays ?? 7;
169	    } catch (_) {}
170	
171	    if (!enabled) return;
172	
173	    const calDir = path.join(repoRoot, 'data', 'calibration');
174	    let latestMtime = 0;
175	    try {
176	      const files = fs.readdirSync(calDir).filter(f => f.startsWith('brain-refresh-') && f.endsWith('.md'));
177	      for (const f of files) {
178	        const mt = fs.statSync(path.join(calDir, f)).mtimeMs;
179	        if (mt > latestMtime) latestMtime = mt;
180	      }
181	    } catch (_) {}
182	
183	    const ageDays = (Date.now() - latestMtime) / 86400000;
184	    if (latestMtime > 0 && ageDays < minDays) return;
185	
186	    const py = path.join(repoRoot, '.claude', 'skills', '.venv', 'Scripts', 'python.exe');
187	    const script = path.join(repoRoot, '.claude', 'skills', 'business', 'transaction-layer', 'nui-hunter', 'scripts', 'brain-refresh-weekly.py');
188	
189	    if (!fs.existsSync(py) || !fs.existsSync(script)) return;
190	
191	    const logDir = path.join(repoRoot, '.claude', 'hooks', '.logs');
192	    fs.mkdirSync(logDir, { recursive: true });
193	    const ageLabel = latestMtime === 0 ? 'never' : `${ageDays.toFixed(1)}d`;
194	    fs.appendFileSync(
195	      path.join(logDir, 'brain-refresh-trigger.log'),
196	      `${new Date().toISOString()} spawn brain-refresh-weekly.py (age=${ageLabel})\n`
197	    );
198	
199	    const child = spawn(py, [script], { detached: true, stdio: 'ignore', cwd: repoRoot });
200	    child.unref();
201	    log(tag, `launched (age=${ageLabel})`);
202	  } catch (e) {
203	    log(tag, e.message);
204	  }
205	}
206	
207	// ---------------------------------------------------------------------------
208	// Main
209	// ---------------------------------------------------------------------------
210	
211	try {
212	  const repoRoot = path.resolve(__dirname, '..', '..');
213	  metaLearnerWeekly(repoRoot);
214	  cognitiveConsolidation(repoRoot);
215	  brainRefreshWeekly(repoRoot);
216	} catch (e) {
217	  if (DEBUG) console.error(`[cron-weekly-runner] ${e.message}`);
218	}
219	
220	process.exit(0);
