2	/**
3	 * SessionEnd hook — auto-run query feedback analyzer.
4	 *
5	 * Fires: when a session ends. Reads _query_log.jsonl and writes
6	 *        _query_insights.json + (if enabled) _auto_topic_rules.json
7	 *        sandbox additions.
8	 *
9	 * Safe defaults:
10	 *   - Skip if log doesn't exist or is empty
11	 *   - Skip if log hasn't grown since last analyze (idempotent)
12	 *   - Always exit 0 (fail-closed)
13	 */
14	
15	'use strict';
16	
17	const fs = require('fs');
18	const path = require('path');
19	const { execFileSync } = require('child_process');
20	
21	const HOOK_NAME = 'session-end-feedback-analyze';
22	const REPO_ROOT = path.resolve(__dirname, '..', '..');
23	const KE_ROOT = path.join(
24	  REPO_ROOT, '.claude', 'skills', 'business', 'knowledge-extraction'
25	);
26	const LOG_PATH = path.join(KE_ROOT, 'data', 'tiktok', '_query_log.jsonl');
27	const INSIGHTS_PATH = path.join(KE_ROOT, 'data', 'tiktok', '_query_insights.json');
28	const STATE_PATH = path.join(REPO_ROOT, '.claude', 'logs', 'hooks',
29	                             `${HOOK_NAME}.state.json`);
30	const HOOK_LOG_DIR = path.join(REPO_ROOT, '.claude', 'logs', 'hooks');
31	const HOOK_LOG_PATH = path.join(HOOK_LOG_DIR, `${HOOK_NAME}.log`);
32	const VENV_PY_WIN = path.join(REPO_ROOT, '.claude', 'skills', '.venv',
33	                              'Scripts', 'python.exe');
34	const VENV_PY_NIX = path.join(REPO_ROOT, '.claude', 'skills', '.venv',
35	                              'bin', 'python3');
36	
37	function logEntry(entry) {
38	  try {
39	    if (!fs.existsSync(HOOK_LOG_DIR)) fs.mkdirSync(HOOK_LOG_DIR, { recursive: true });
40	    fs.appendFileSync(
41	      HOOK_LOG_PATH,
42	      JSON.stringify({ ts: new Date().toISOString(), ...entry }) + '\n'
43	    );
44	  } catch (_) {}
45	}
46	
47	function pickPython() {
48	  if (fs.existsSync(VENV_PY_WIN)) return VENV_PY_WIN;
49	  if (fs.existsSync(VENV_PY_NIX)) return VENV_PY_NIX;
50	  return null;
51	}
52	
53	function readState() {
54	  try {
55	    if (fs.existsSync(STATE_PATH)) {
56	      return JSON.parse(fs.readFileSync(STATE_PATH, 'utf8'));
57	    }
58	  } catch (_) {}
59	  return { last_size: 0 };
60	}
61	
62	function writeState(state) {
63	  try {
64	    if (!fs.existsSync(HOOK_LOG_DIR)) fs.mkdirSync(HOOK_LOG_DIR, { recursive: true });
65	    fs.writeFileSync(STATE_PATH, JSON.stringify(state));
66	  } catch (_) {}
67	}
68	
69	function main() {
70	  if (!fs.existsSync(LOG_PATH)) {
71	    logEntry({ status: 'skip', reason: 'no query log' });
72	    process.exit(0);
73	  }
74	  const stat = fs.statSync(LOG_PATH);
75	  const state = readState();
76	  if (stat.size <= state.last_size) {
77	    logEntry({ status: 'skip', reason: 'log unchanged', size: stat.size });
78	    process.exit(0);
79	  }
80	
81	  const py = pickPython();
82	  if (!py) {
83	    logEntry({ status: 'skip', reason: 'no venv python' });
84	    process.exit(0);
85	  }
86	
87	  try {
88	    execFileSync(
89	      py,
90	      ['scripts/run-feedback-analysis.py', '--auto-apply'],
91	      { cwd: KE_ROOT, env: { ...process.env, PYTHONIOENCODING: 'utf-8' },
92	        stdio: 'ignore', timeout: 60000 }
93	    );
94	    writeState({ last_size: stat.size });
95	    logEntry({ status: 'ok', size: stat.size,
96	               insights_path: INSIGHTS_PATH });
97	  } catch (e) {
98	    logEntry({ status: 'error', error: e.message });
99	  }
100	  process.exit(0);
101	}
102	
103	try { main(); } catch (e) { logEntry({ status: 'crash', error: e.message }); process.exit(0); }
